import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const MatchmakingPage = () => {
  const [entryFee, setEntryFee] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [matchInfo, setMatchInfo] = useState(null); // নতুন স্টেট ম্যাচ ডিটেইলস দেখানোর জন্য

  const navigate = useNavigate();

  const handleMatch = async () => {
    const token = localStorage.getItem("token");
    if (!token) {
      setError("⚠️ দয়া করে আগে লগইন করুন।");
      return;
    }

    try {
      setLoading(true);
      setError("");
      setMatchInfo(null);

      const response = await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee: parseFloat(entryFee) },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      if (response.data.status === "WAITING") {
        setError("⏳ প্রতিপক্ষের জন্য অপেক্ষা করা হচ্ছে...");
      } else {
        const { gameId, player1, player2 } = response.data;

        // ম্যাচ ইনফো UI-তে দেখানো হবে
        setMatchInfo({ gameId, player1, player2 });

        // কিছুক্ষণ পরে অটো রিডাইরেক্ট করবে LudoBoard.jsx এর রুটে
        setTimeout(() => {
          navigate(`/game/${gameId}`);
        }, 3000); // ৩ সেকেন্ড পরে রিডাইরেক্ট (চাহিদা মতো পরিবর্তন করতে পারো)
      }
    } catch (err) {
      setError(err.response?.data?.error || "কিছু ভুল হয়েছে, আবার চেষ্টা করুন।");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gradient-to-r from-blue-100 to-blue-300">
      <div className="bg-white p-8 rounded-lg shadow-xl w-full max-w-md">
        <h2 className="text-2xl font-bold text-center text-blue-700 mb-6">
          🎯 ম্যাচ খুঁজুন
        </h2>

        <input
          type="number"
          placeholder="এন্ট্রি ফি লিখুন (যেমন: 10)"
          value={entryFee}
          onChange={(e) => setEntryFee(e.target.value)}
          className="w-full p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4"
        />

        <button
          onClick={handleMatch}
          disabled={loading}
          className={`w-full flex justify-center items-center gap-2 py-3 rounded-md text-white font-semibold transition ${
            loading
              ? "bg-gray-400 cursor-not-allowed"
              : "bg-blue-600 hover:bg-blue-700"
          }`}
        >
          {loading && (
            <svg
              className="animate-spin h-5 w-5 text-white"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                className="opacity-25"
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              ></circle>
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8v8z"
              ></path>
            </svg>
          )}
          {loading ? "ম্যাচ হচ্ছে..." : "ম্যাচ খুঁজুন"}
        </button>

        {error && (
          <p className="mt-4 text-center text-sm text-red-500 font-medium">
            {error}
          </p>
        )}

        {/* ম্যাচ ডিটেইলস দেখানোর জন্য */}
        {matchInfo && (
          <div className="mt-6 bg-blue-100 p-4 rounded-md text-center text-blue-700">
            <p>ম্যাচ সফল হয়েছে!</p>
            <p>গেম আইডি: <strong>{matchInfo.gameId}</strong></p>
            <p>প্লেয়ার ১: <strong>{matchInfo.player1}</strong></p>
            <p>প্লেয়ার ২: <strong>{matchInfo.player2}</strong></p>
            <p>৩ সেকেন্ড পরে গেম পেজে নিয়ে যাওয়া হবে...</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default MatchmakingPage;
